from __future__ import annotations

import argparse
import gzip
import json
import os
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, unquote, urlsplit

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState
from .activity import NeuralActivity
from .atlas import NeuralAtlas


class NeuralSurface:
    def __init__(self, root: Path, *, inventory: Path | None = None, trace: bool = True) -> None:
        self.root = root.expanduser().resolve()
        self.atlas = NeuralAtlas(self.root, inventory=inventory)
        self.activity = NeuralActivity(self.root, atlas=self.atlas)
        self.trace = bool(trace)
        self.invention_usdz_root = self.root / "var" / "inventions" / "usdz"

    def start(self) -> None:
        self.invention_usdz_root.mkdir(parents=True, exist_ok=True)
        self.atlas.build()
        if self.trace:
            self.activity.start_trace()

    def stop(self) -> None:
        self.activity.stop_trace()


class NeuralHandler(BaseHTTPRequestHandler):
    server_version = "EIRA2Neural/2"

    def log_message(self, format: str, *args: Any) -> None:
        return

    @property
    def surface(self) -> NeuralSurface:
        return self.server.surface  # type: ignore[attr-defined]

    @property
    def web_root(self) -> Path:
        return Path(__file__).resolve().parent / "web"

    def _security_headers(self) -> None:
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Opener-Policy", "same-origin")
        self.send_header(
            "Permissions-Policy",
            "microphone=(self), camera=(self), geolocation=(self), accelerometer=(self), gyroscope=(self)",
        )
        self.send_header(
            "Content-Security-Policy",
            "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; "
            "connect-src 'self'; media-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
        )

    def _cors(self) -> None:
        origin = str(self.headers.get("Origin") or "").strip()
        host = str(self.headers.get("Host") or "").strip()
        if origin and host:
            parsed = urlsplit(origin)
            if parsed.netloc == host and parsed.scheme in {"http", "https"}:
                self.send_header("Access-Control-Allow-Origin", origin)
                self.send_header("Vary", "Origin")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def _bytes(self, code: int, raw: bytes, content_type: str, *, cache: str = "no-store") -> None:
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", cache)
        self._security_headers()
        self._cors()
        self.end_headers()
        try:
            self.wfile.write(raw)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return

    def _json(self, code: int, payload: Any) -> None:
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        accepted = str(self.headers.get("Accept-Encoding") or "")
        if "gzip" in accepted.casefold() and len(raw) > 4096:
            raw = gzip.compress(raw, compresslevel=5)
            self.send_response(code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Encoding", "gzip")
            self.send_header("Content-Length", str(len(raw)))
            self.send_header("Cache-Control", "no-store")
            self._security_headers()
            self._cors()
            self.end_headers()
            try:
                self.wfile.write(raw)
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                pass
            return
        self._bytes(code, raw, "application/json; charset=utf-8")

    def _range_error(self, size: int) -> None:
        raw = json.dumps({"ok": False, "error": "invalid_range"}, separators=(",", ":")).encode("utf-8")
        self.send_response(416)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Range", f"bytes */{max(0, int(size))}")
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", "no-store")
        self._security_headers()
        self._cors()
        self.end_headers()
        if self.command != "HEAD":
            try:
                self.wfile.write(raw)
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                pass

    def do_OPTIONS(self) -> None:
        self.send_response(204)
        self._security_headers()
        self._cors()
        self.send_header("Content-Length", "0")
        self.end_headers()

    @staticmethod
    def _int(query: dict[str, list[str]], key: str, default: int) -> int:
        try:
            return int((query.get(key) or [default])[0])
        except (TypeError, ValueError):
            return default

    def _static(self, name: str, content_type: str) -> None:
        path = self.web_root / name
        if not path.is_file():
            self._json(503, {"ok": False, "error": f"neural_asset_missing:{name}"})
            return
        self._bytes(200, path.read_bytes(), content_type, cache="no-cache")

    def _serve_file(self, path: Path, content_type: str, *, filename: str | None = None) -> None:
        try:
            resolved = path.resolve(strict=True)
        except OSError:
            return self._json(404, {"ok": False, "error": "artifact_not_found"})
        try:
            resolved.relative_to(self.surface.invention_usdz_root.resolve())
        except ValueError:
            return self._json(403, {"ok": False, "error": "artifact_path_rejected"})
        if not resolved.is_file():
            return self._json(404, {"ok": False, "error": "artifact_not_found"})

        try:
            size = resolved.stat().st_size
        except OSError:
            return self._json(404, {"ok": False, "error": "artifact_not_found"})
        start, end = 0, max(0, size - 1)
        status = 200
        raw_range = str(self.headers.get("Range") or "").strip()
        if raw_range:
            if not raw_range.startswith("bytes=") or "," in raw_range or size <= 0:
                return self._range_error(size)
            token = raw_range[6:].strip()
            if not token or "-" not in token:
                return self._range_error(size)
            left, right = token.split("-", 1)
            try:
                if left:
                    start = int(left)
                    if start < 0 or start >= size:
                        return self._range_error(size)
                    if right:
                        end = int(right)
                        if end < start:
                            return self._range_error(size)
                        end = min(end, size - 1)
                    else:
                        end = size - 1
                else:
                    suffix = int(right)
                    if suffix <= 0:
                        return self._range_error(size)
                    suffix = min(suffix, size)
                    start = size - suffix
                    end = size - 1
                status = 206
            except ValueError:
                return self._range_error(size)

        length = 0 if size == 0 else end - start + 1
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(length))
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Cache-Control", "no-cache")
        if filename:
            safe_name = filename.replace('"', "")
            self.send_header("Content-Disposition", f'inline; filename="{safe_name}"')
        if status == 206:
            self.send_header("Content-Range", f"bytes {start}-{end}/{size}")
        self._security_headers()
        self._cors()
        self.end_headers()
        if self.command == "HEAD" or length <= 0:
            return
        try:
            with resolved.open("rb") as handle:
                handle.seek(start)
                remaining = length
                while remaining > 0:
                    chunk = handle.read(min(1024 * 1024, remaining))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    remaining -= len(chunk)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError, OSError):
            return

    def _list_usdz(self) -> dict[str, Any]:
        root = self.surface.invention_usdz_root
        candidates: list[tuple[int, Path, int]] = []
        if root.is_dir():
            for path in root.glob("*.usdz"):
                try:
                    if path.is_symlink() or not path.is_file():
                        continue
                    stat = path.stat()
                except OSError:
                    continue
                candidates.append((stat.st_mtime_ns, path, stat.st_size))
        candidates.sort(key=lambda item: item[0], reverse=True)
        rows = [
            {
                "name": path.name,
                "size": size,
                "modified_ns": modified_ns,
                "href": f"/inventions/usdz/{path.name}",
                "quick_look": True,
                "content_type": "model/vnd.usdz+zip",
            }
            for modified_ns, path, size in candidates
        ]
        return {"ok": True, "schema": "eira2_invention_usdz_index_v1", "count": len(rows), "models": rows}

    def do_HEAD(self) -> None:
        parsed = urlsplit(self.path)
        prefix = "/inventions/usdz/"
        if parsed.path.startswith(prefix):
            name = unquote(parsed.path[len(prefix):])
            if "/" in name or "\\" in name or not name.casefold().endswith(".usdz"):
                return self._json(400, {"ok": False, "error": "invalid_usdz_name"})
            return self._serve_file(self.surface.invention_usdz_root / name, "model/vnd.usdz+zip", filename=name)
        self.send_response(404)
        self.send_header("Content-Length", "0")
        self._security_headers()
        self.end_headers()

    def do_GET(self) -> None:
        parsed = urlsplit(self.path)
        path = parsed.path
        query = parse_qs(parsed.query, keep_blank_values=False)

        if path in {"/", "/neural", "/neural/"}:
            revamp = Path("/media/domenicleonetti/easystore/EIRA/LIVE/eira2_server_revamp/static/index.html")
            if revamp.is_file():
                return self._bytes(200, revamp.read_bytes(), "text/html; charset=utf-8", cache="no-cache")
            return self._static("index.html", "text/html; charset=utf-8")

        if path == "/reference.css":
            refcss = Path("/media/domenicleonetti/easystore/EIRA/LIVE/eira2_server_revamp/static/reference.css")
            if refcss.is_file():
                return self._bytes(200, refcss.read_bytes(), "text/css; charset=utf-8", cache="no-cache")
        if path == "/reference.js":
            p = Path("/media/domenicleonetti/easystore/EIRA/LIVE/eira2_server_revamp/static/reference.js")
            if p.is_file():
                return self._bytes(200, p.read_bytes(), "application/javascript; charset=utf-8", cache="no-cache")
        if path in {"/inventions", "/inventions/"}:
            return self._static("invention.html", "text/html; charset=utf-8")
        if path == "/neural/app.js":
            return self._static("app.js", "application/javascript; charset=utf-8")
        if path == "/neural/communication.js":
            return self._static("communication.js", "application/javascript; charset=utf-8")
        if path == "/neural/invention.js":
            return self._static("invention.js", "application/javascript; charset=utf-8")
        if path == "/neural/style.css":
            return self._static("style.css", "text/css; charset=utf-8")
        if path == "/neural/invention.css":
            return self._static("invention.css", "text/css; charset=utf-8")
        if path == "/neural/ar-placeholder.svg":
            return self._static("ar-placeholder.svg", "image/svg+xml")

        if path == "/health":
            overview = self.surface.atlas.overview()
            return self._json(
                200,
                {
                    "ok": True,
                    "service": "eira2.neural",
                    "inventory_neuron_count": overview["inventory_neuron_count"],
                    "conductive_fiber_count": overview["conductive_fiber_count"],
                    "tracer_enabled": self.surface.activity.enabled,
                    "invention_usdz_quick_look": True,
                },
            )

        if path == "/api/inventions/usdz":
            return self._json(200, self._list_usdz())

        usdz_prefix = "/inventions/usdz/"
        if path.startswith(usdz_prefix):
            name = unquote(path[len(usdz_prefix):])
            if "/" in name or "\\" in name or not name.casefold().endswith(".usdz"):
                return self._json(400, {"ok": False, "error": "invalid_usdz_name"})
            return self._serve_file(self.surface.invention_usdz_root / name, "model/vnd.usdz+zip", filename=name)

        if path == "/api/neural/overview":
            return self._json(200, self.surface.atlas.overview())

        if path == "/api/neural/nodes":
            cluster = (query.get("cluster") or [None])[0]
            cursor = self._int(query, "cursor", 0)
            limit = self._int(query, "limit", 1500)
            include_paths = (query.get("paths") or ["1"])[0] not in {"0", "false", "no"}
            return self._json(
                200,
                self.surface.atlas.page(
                    cluster=cluster,
                    cursor=cursor,
                    limit=limit,
                    include_paths=include_paths,
                ),
            )

        if path == "/api/neural/fibers":
            cluster = (query.get("cluster") or [None])[0]
            limit = self._int(query, "limit", 20000)
            return self._json(200, self.surface.atlas.fibers_for(cluster=cluster, limit=limit))

        if path == "/api/neural/activity":
            try:
                window = float((query.get("window") or ["2.4"])[0])
            except (TypeError, ValueError):
                window = 2.4
            limit = self._int(query, "limit", 400)
            return self._json(200, self.surface.activity.snapshot(window_seconds=window, limit=limit))

        if path == "/api/neural/search":
            term = (query.get("q") or [""])[0]
            limit = self._int(query, "limit", 100)
            return self._json(200, self.surface.atlas.search(term, limit=limit))

        prefix = "/api/neural/neuron/"
        if path.startswith(prefix):
            neuron_id = unquote(path[len(prefix):])
            row = self.surface.atlas.neuron(neuron_id)
            if row is None:
                return self._json(404, {"ok": False, "error": "neuron_not_found"})
            return self._json(200, {"ok": True, "schema": "eira2_neuron_detail_v1", "neuron": row})

        self._json(404, {"ok": False, "error": "not_found"})


class NeuralHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], surface: NeuralSurface) -> None:
        self.surface = surface
        super().__init__(address, NeuralHandler)


class NeuralHTTPService:
    spec = ServiceSpec(
        "interfaces.neural_ui",
        required=False,
        dependencies=("kernel.events",),
        start_timeout_seconds=45.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(
        self,
        root: Path,
        *,
        host: str = "127.0.0.1",
        port: int = 8782,
        inventory: Path | None = None,
        trace: bool = True,
    ) -> None:
        self.root = root.expanduser().resolve()
        self.host = host
        self.port = int(port)
        self.surface = NeuralSurface(self.root, inventory=inventory, trace=trace)
        self._state = ServiceState.DECLARED
        self._server: NeuralHTTPServer | None = None
        self._thread: threading.Thread | None = None

    @property
    def url(self) -> str:
        return f"http://{self.host}:{self.port}/neural/"

    async def start(self, context: RuntimeContext) -> None:
        self.surface.start()
        server = NeuralHTTPServer((self.host, self.port), self.surface)
        self.port = int(server.server_address[1])
        self._server = server
        self._thread = threading.Thread(
            target=server.serve_forever,
            name="eira2-neural-http",
            kwargs={"poll_interval": 0.2},
            daemon=True,
        )
        self._thread.start()
        self._state = ServiceState.READY

    async def stop(self) -> None:
        if self._server is not None:
            self._server.shutdown()
            self._server.server_close()
        if self._thread is not None:
            self._thread.join(timeout=3.0)
        self.surface.stop()
        self._server = None
        self._thread = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        detail = self.url if self._state == ServiceState.READY else ""
        return Health(self._state, detail)


def run(root: Path, host: str, port: int, inventory: Path | None, trace: bool) -> None:
    surface = NeuralSurface(root, inventory=inventory, trace=trace)
    surface.start()
    server = NeuralHTTPServer((host, port), surface)
    actual_port = int(server.server_address[1])
    print(f"EIRA 2.0 neural surface: http://{host}:{actual_port}/neural/", flush=True)
    try:
        server.serve_forever(poll_interval=0.2)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        surface.stop()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument("--host", default=os.getenv("EIRA2_NEURAL_HOST", "127.0.0.1"))
    parser.add_argument("--port", type=int, default=int(os.getenv("EIRA2_NEURAL_PORT", "8782")))
    parser.add_argument("--inventory", type=Path, default=None)
    parser.add_argument("--no-trace", action="store_true")
    args = parser.parse_args()
    run(args.root.resolve(), args.host, args.port, args.inventory, not args.no_trace)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import ast
import csv
import hashlib
import json
import os
from collections import Counter, defaultdict
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Any, Iterable, Iterator


_INVENTORY_ENV = "EIRA2_NEURAL_INVENTORY"
_EXCLUDED_SCAN_PARTS = {".git", "__pycache__", ".pytest_cache"}
_CODE_SUFFIXES = {".py", ".js", ".ts", ".tsx", ".jsx", ".html", ".css", ".json", ".yaml", ".yml", ".toml", ".sh"}
_CONDUCTIVE_KINDS = {"python_import", "declared_runtime_dependency", "runtime_call"}


def _normalize(value: Any) -> str:
    return str(value or "").replace("\\", "/").strip()


def stable_neuron_id(path: str) -> str:
    """Stable opaque neuron id; paths remain metadata, not identifiers."""
    clean = _normalize(path)
    digest = hashlib.blake2b(clean.encode("utf-8", errors="replace"), digest_size=12).hexdigest()
    return f"neuron:{digest}"


def _logical_path(raw: str, root: Path) -> str:
    value = _normalize(raw)
    if not value:
        return ""
    root_text = _normalize(root.resolve())
    if value == root_text:
        return "."
    if value.startswith(root_text.rstrip("/") + "/"):
        return value[len(root_text.rstrip("/")) + 1 :]
    marker = "/EIRA/LIVE/"
    pos = value.casefold().find(marker.casefold())
    if pos >= 0:
        return value[pos + len(marker) :]
    if value.startswith("pi:/"):
        return "external/pi/" + value[3:].lstrip("/")
    if value.startswith("/"):
        return "external/fs/" + value.lstrip("/")
    return value.lstrip("./")


def _entry_path(row: dict[str, Any]) -> str:
    for key in ("source_path", "path", "absolute_path", "relative_path"):
        if row.get(key):
            return _normalize(row[key])
    return ""


def _entry_kind(row: dict[str, Any]) -> str:
    raw = str(row.get("entry_type") or row.get("type") or row.get("kind") or "file").casefold()
    return "directory" if raw in {"dir", "directory", "folder"} else "file"


def _disposition(row: dict[str, Any]) -> str:
    return str(row.get("disposition") or row.get("classification") or "unclassified")


def _iter_json_payload(value: Any) -> Iterator[dict[str, Any]]:
    if isinstance(value, list):
        for row in value:
            if isinstance(row, dict):
                yield row
        return
    if isinstance(value, dict):
        for key in ("entries", "files", "manifest", "inventory"):
            rows = value.get(key)
            if isinstance(rows, list):
                for row in rows:
                    if isinstance(row, dict):
                        yield row
                return
        if _entry_path(value):
            yield value
            return
    raise ValueError("neural_inventory_json_shape_unsupported")


def inventory_rows(path: Path) -> Iterator[dict[str, Any]]:
    suffix = path.suffix.casefold()
    if suffix == ".csv":
        with path.open("r", encoding="utf-8", errors="replace", newline="") as handle:
            yield from csv.DictReader(handle)
        return
    text = path.read_text(encoding="utf-8", errors="replace")
    if not text.strip():
        return
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        for number, line in enumerate(text.splitlines(), 1):
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(f"neural_inventory_jsonl_invalid:{number}:{error.msg}") from error
            if not isinstance(row, dict):
                raise ValueError(f"neural_inventory_row_not_object:{number}")
            yield row
        return
    yield from _iter_json_payload(payload)


def inventory_candidates(root: Path) -> tuple[Path, ...]:
    env = os.getenv(_INVENTORY_ENV, "").strip()
    values = []
    if env:
        values.append(Path(env).expanduser())
    values.extend(
        [
            root / "migration_ledger.csv",
            root / "eira2" / "migration_ledger.csv",
            root / "var" / "migration_ledger.csv",
            root / "eira2" / "var" / "migration_ledger.csv",
            root / "eira2_organization.json",
            root / "eira2" / "eira2_organization.json",
            root / "var" / "eira2_organization.json",
        ]
    )
    out: list[Path] = []
    for value in values:
        resolved = value.resolve() if value.is_absolute() else (root / value).resolve()
        if resolved not in out:
            out.append(resolved)
    return tuple(out)


def _filesystem_rows(root: Path) -> Iterator[dict[str, Any]]:
    for path in root.rglob("*"):
        try:
            rel = path.relative_to(root)
        except ValueError:
            continue
        if any(part in _EXCLUDED_SCAN_PARTS for part in rel.parts):
            continue
        try:
            is_dir = path.is_dir()
            size = 0 if is_dir else path.stat().st_size
        except OSError:
            continue
        yield {
            "path": str(path),
            "type": "directory" if is_dir else "file",
            "size": size,
            "disposition": "runtime_scan_fallback",
        }


def _cluster_for(logical: str) -> str:
    parts = PurePosixPath(logical).parts
    if len(parts) >= 2 and parts[0] == "extensions":
        return f"extension:{parts[1]}"
    if len(parts) >= 3 and parts[:2] == ("eira2", "eira2"):
        return f"eira2:{parts[2]}"
    if parts:
        return f"root:{parts[0]}"
    return "root:."


def _anatomy_for(cluster: str) -> tuple[str, bool]:
    low = cluster.casefold()
    spine = any(token in low for token in ("conversation", "kernel", "state", "memory", "delivery", "evidence"))
    if spine:
        return "midline", True
    bit = int(hashlib.blake2b(cluster.encode(), digest_size=1).hexdigest(), 16) & 1
    return ("left" if bit == 0 else "right"), False


def _activity_class(disposition: str, logical: str) -> str:
    low = disposition.casefold()
    if low == "migrate_runtime" or logical.startswith(("eira2/", "extensions/")):
        return "runtime"
    if low == "migrate_state":
        return "state"
    if low == "migrate_artifact":
        return "artifact"
    if low in {"retain_evidence", "regenerate", "external_dependency", "secret_reference"}:
        return low
    return "other"


@dataclass(frozen=True, slots=True)
class Neuron:
    id: str
    path: str
    logical_path: str
    kind: str
    cluster: str
    hemisphere: str
    spine: bool
    disposition: str
    activity_class: str
    size: int
    suffix: str
    conductive_capable: bool
    synthetic: bool = False

    def as_dict(self, *, include_path: bool = True) -> dict[str, Any]:
        row = {
            "id": self.id,
